import { Ionicons } from "@expo/vector-icons";
import type { CategoryDto } from "@amiyo/contracts";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useRouter } from "expo-router";
import type { User } from "@firebase/auth";
import { useEffect, useMemo, useRef, useState } from "react";
import { ActivityIndicator, Image, Pressable, StyleSheet, Text, TextInput, useWindowDimensions, View } from "react-native";
import { ModuleCard } from "../../ui/ModuleCard";
import { minorToMajorInput, parseMajorToMinor } from "../../ui/money";
import { Screen } from "../../ui/Screen";
import { colors, radius, spacing } from "../../ui/tokens";
import { useCurrentUser } from "../auth/use-current-user";
import { createVendorProduct, getCategories, getVendorProducts, replaceVendorProductMedia, replaceVendorProductVariants, updateVendorProduct } from "../catalog/catalog.api";
import { pickAndUploadImage } from "../media/media.api";
import { ProductCategorySelect } from "./components/ProductCategorySelect";
import { getVendorWorkspace } from "./vendor.api";

type VariantDraft = { id?: string; color: string; size: string; sku: string; title: string; price: string; compareAt: string; stock: string; active: boolean };
type MediaDraft = { id?: string; uploadId?: string; uri: string; altText: string; variantSku: string };
const initial = { name: "", brand: "", categoryId: "", description: "", colors: "", sizes: "" };
const emptyVariant = (): VariantDraft => ({ color: "", size: "", sku: "", title: "Default", price: "", compareAt: "", stock: "0", active: true });

export function VendorProductFormScreen({ id }: { id?: string }) {
  const editing = Boolean(id);
  const compact = useWindowDimensions().width < 620;
  const router = useRouter();
  const user = useCurrentUser();
  const activeUid = useRef(user?.uid); activeUid.current = user?.uid;
  const cache = useQueryClient();
  const products = useQuery({ queryKey: ["vendor", "products", user?.uid], queryFn: () => getVendorProducts(user!), enabled: Boolean(user && editing), retry: false });
  const categories = useQuery({ queryKey: ["catalog", "categories"], queryFn: getCategories });
  const workspace = useQuery({ queryKey: ["vendor", "workspace", user?.uid], queryFn: () => getVendorWorkspace(user!), enabled: Boolean(user && !editing), retry: false });
  const product = products.data?.find((item) => item.id === id);
  const [form, setForm] = useState(initial);
  const [variants, setVariants] = useState<VariantDraft[]>([emptyVariant()]);
  const [media, setMedia] = useState<MediaDraft[]>([]);
  const [attributeValues, setAttributeValues] = useState<Record<string, unknown>>({});
  const [uploading, setUploading] = useState(false);
  const [uploadError, setUploadError] = useState("");
  const [formError, setFormError] = useState("");

  useEffect(() => { setForm(initial); setVariants([emptyVariant()]); setMedia([]); setAttributeValues({}); setUploading(false); setUploadError(""); setFormError(""); }, [user?.uid, id]);

  useEffect(() => {
    if (!product) return;
    const productVariants = product.variants.map((variant) => ({ id: variant.id, color: textAttribute(variant.attributes?.color), size: textAttribute(variant.attributes?.size), sku: variant.sku, title: variant.title, price: decimal(variant.price.amountMinor), compareAt: variant.compareAtPrice ? decimal(variant.compareAtPrice.amountMinor) : "", stock: String(variant.availableQuantity), active: variant.active }));
    setForm({ name: product.name, brand: product.brand ?? "", categoryId: product.categoryId, description: product.description ?? "", colors: unique(productVariants.map((item) => item.color)).join(", "), sizes: unique(productVariants.map((item) => item.size)).join(", ") });
    setVariants(productVariants.length ? productVariants : [emptyVariant()]);
    setMedia(product.media.map((item) => ({ id: item.id, uri: item.url, altText: item.altText ?? "", variantSku: product.variants.find((variant) => variant.id === item.variantId)?.sku ?? "" })));
    setAttributeValues(product.dynamicAttributes ?? {});
  }, [product]);

  const categoryAttributes = useMemo(() => inheritedAttributes(categories.data ?? [], form.categoryId), [categories.data, form.categoryId]);
  const requiredAttributesValid = categoryAttributes.filter((attribute) => attribute.required).every((attribute) => hasAttributeValue(attributeValues[attribute.key]));
  const uniqueSkus = new Set(variants.map((variant) => variant.sku.trim().toUpperCase())).size === variants.length;
  const validVariants = variants.every(validVariant);
  const workspaceReady = editing ? Boolean(product) : Boolean(workspace.data?.shops[0]);
  const valid = form.name.trim().length >= 3 && Boolean(form.categoryId) && variants.length > 0 && variants.length <= 100 && validVariants && uniqueSkus && requiredAttributesValid && workspaceReady;
  const informationComplete = form.name.trim().length >= 3 && Boolean(form.categoryId) && requiredAttributesValid;
  const mediaComplete = media.length > 0;
  const variantsComplete = variants.length > 0 && variants.length <= 100 && validVariants && uniqueSkus;
  const readinessChecks = [
    { label: "Product identity", complete: form.name.trim().length >= 3 && Boolean(form.categoryId) },
    { label: "Category details", complete: requiredAttributesValid },
    { label: "Product media", complete: mediaComplete },
    { label: "Sellable variants", complete: variantsComplete },
    { label: "Shop connection", complete: workspaceReady }
  ];
  const readiness = Math.round((readinessChecks.filter((item) => item.complete).length / readinessChecks.length) * 100);
  const save = useMutation({ retry: false, mutationFn: async (owner: User) => {
    const payload = variants.map((variant) => ({ ...(variant.id ? { id: variant.id } : {}), sku: variant.sku.trim().toUpperCase(), title: variant.title.trim(), attributes: { ...(variant.color ? { color: variant.color } : {}), ...(variant.size ? { size: variant.size } : {}) }, priceMinor: minor(variant.price), compareAtMinor: variant.compareAt ? minor(variant.compareAt) : null, currency: "BDT", onHand: Number(variant.stock), active: variant.active }));
    let current = editing
      ? await updateVendorProduct(owner, id!, { version: product!.version, name: form.name, brand: form.brand.trim() || null, categoryId: form.categoryId, description: form.description.trim() || null, dynamicAttributes: attributeValues })
      : await createVendorProduct(owner, { shopId: workspace.data!.shops[0]!.id, categoryId: form.categoryId, name: form.name, slug: slug(form.name), brand: form.brand.trim() || null, description: form.description.trim() || null, dynamicAttributes: attributeValues, variants: payload.map(({ id: _id, active: _active, ...variant }) => variant) });
    if (editing) current = await replaceVendorProductVariants(owner, current.id, { version: current.version, variants: payload });
    if (editing || media.length) current = await replaceVendorProductMedia(owner, current.id, { version: current.version, items: media.map((item, index) => ({ ...(item.id ? { id: item.id } : { uploadId: item.uploadId! }), variantId: current.variants.find((variant) => variant.sku === item.variantSku)?.id ?? null, altText: item.altText.trim() || null, displayOrder: index })) });
    return current;
  }, onSuccess: async (saved, owner) => { if (activeUid.current === owner.uid) { await cache.invalidateQueries({ queryKey: ["vendor", "products", owner.uid] }); router.replace(`/vendor/products/${saved.id}` as never); } } });

  const uploadImage = async () => {
    if (!user || media.length >= 12) return;
    setUploadError(""); setUploading(true);
    const owner = user!;
    try { const result = await pickAndUploadImage(owner, "product"); if (result && activeUid.current === owner.uid) setMedia((items) => [...items, { uploadId: result.id, uri: result.localUri || result.publicUrl || "", altText: form.name, variantSku: "" }]); }
    catch (error) { if (activeUid.current === owner.uid) setUploadError(error instanceof Error ? error.message : "Image upload failed"); }
    finally { if (activeUid.current === owner.uid) setUploading(false); }
  };
  const generateVariants = () => {
    const colors = values(form.colors); const sizes = values(form.sizes);
    if (!colors.length && !sizes.length) return;
    const combinations = (colors.length ? colors : [""]).flatMap((color) => (sizes.length ? sizes : [""]).map((size) => ({ color, size })));
    if (combinations.length > 100) { setFormError("A product can have up to 100 variants. Reduce colors or sizes."); return; }
    setFormError("");
    setVariants(combinations.map(({ color, size }, index) => { const existing = variants.find((item) => item.color.toLowerCase() === color.toLowerCase() && item.size.toLowerCase() === size.toLowerCase()); return existing ?? { ...emptyVariant(), color, size, title: [color, size].filter(Boolean).join(" / ") || "Default", sku: makeSku(form.name, color, size, index) }; }));
  };
  const updateVariant = (index: number, change: Partial<VariantDraft>) => setVariants((items) => items.map((item, itemIndex) => itemIndex === index ? { ...item, ...change } : item));

  if (editing && products.isLoading) return <Screen title="Loading product"><ActivityIndicator color={colors.primary} /></Screen>;
  if (editing && !product) return <Screen title="Product unavailable" description="This product could not be found in your seller catalog."><Pressable onPress={() => router.replace("/vendor/products")} style={styles.primary}><Text style={styles.primaryText}>Back to products</Text></Pressable></Screen>;
  return <Screen eyebrow="SELLER CATALOG" title={editing ? "Edit product" : "Add a product"} description="Build a complete listing with gallery images, variants, pricing and stock.">
    <View style={[styles.steps, compact && compactStyles.steps]}><Step complete={informationComplete} label="Information" number="1" /><View style={[styles.rail, !informationComplete && styles.railPending]} /><Step complete={mediaComplete} label="Media" number="2" /><View style={[styles.rail, !mediaComplete && styles.railPending]} /><Step complete={variantsComplete} label="Variants" number="3" /></View>
    <View style={[styles.readiness, compact && styles.readinessCompact]}><View style={styles.readinessMain}><View style={styles.readinessTop}><View><Text style={styles.readinessEyebrow}>LISTING READINESS</Text><Text accessibilityRole="header" style={styles.readinessTitle}>{valid ? "Ready to save" : `${readiness}% complete`}</Text></View><View style={[styles.readinessScore, valid && styles.readinessScoreReady]}><Text style={[styles.readinessScoreText, valid && styles.readinessScoreTextReady]}>{readiness}%</Text></View></View><View style={styles.readinessTrack}><View style={[styles.readinessFill, { width: `${readiness}%` }]} /></View><Text style={styles.readinessCopy}>{valid ? "All required listing information is complete." : "Complete the highlighted requirements before saving this product."}</Text></View><View style={[styles.checklist, compact && styles.checklistCompact]}>{readinessChecks.map((item) => <View key={item.label} style={styles.checkItem}><Ionicons color={item.complete ? colors.success : colors.warning} name={item.complete ? "checkmark-circle" : "ellipse-outline"} size={18} /><Text style={[styles.checkText, item.complete && styles.checkTextComplete]}>{item.label}</Text></View>)}</View></View>
    <ModuleCard title="Product information" meta="Use a clear customer-facing name and accurate category."><Field label="Product name *" onChangeText={(name) => setForm({ ...form, name })} placeholder="Enter product name" value={form.name} /><Field label="Brand" onChangeText={(brand) => setForm({ ...form, brand })} placeholder="Brand or manufacturer" value={form.brand} /><ProductCategorySelect categories={categories.data ?? []} onChange={(categoryId) => { setForm({ ...form, categoryId }); setFormError(""); }} value={form.categoryId} /><Field label="Description" multiline onChangeText={(description) => setForm({ ...form, description })} placeholder="Describe features, materials, size and usage" value={form.description} /></ModuleCard>
    {form.categoryId ? <ModuleCard title="Category details" meta={categoryAttributes.length ? "Fields adapt automatically to the selected category." : "This category has no additional product fields."}>{categoryAttributes.length ? <View style={extraStyles.attributeGrid}>{categoryAttributes.map((attribute) => <DynamicAttributeField attribute={attribute} key={attribute.key} onChange={(value) => setAttributeValues((current) => ({ ...current, [attribute.key]: value }))} value={attributeValues[attribute.key]} />)}</View> : <Text style={extraStyles.helper}>You can continue with the standard product information and variants.</Text>}</ModuleCard> : null}
    <ModuleCard title="Product media" meta={`${media.length}/12 images · JPG, PNG or WebP`}><View style={styles.gallery}>{media.map((item, index) => <View key={item.id ?? item.uploadId} style={styles.mediaCard}>{item.uri ? <Image source={{ uri: item.uri }} style={styles.mediaImage} /> : <View style={styles.mediaImageFallback}><Ionicons color={colors.muted} name="image-outline" size={28} /></View>}<Pressable accessibilityLabel="Remove image" onPress={() => setMedia((items) => items.filter((_, itemIndex) => itemIndex !== index))} style={styles.removeMedia}><Ionicons color={colors.surface} name="close" size={16} /></Pressable><TextInput onChangeText={(altText) => setMedia((items) => items.map((entry, itemIndex) => itemIndex === index ? { ...entry, altText } : entry))} placeholder="Image alt text" placeholderTextColor={colors.muted} style={styles.altInput} value={item.altText} /><View style={styles.mediaVariants}><Pressable onPress={() => setMedia((items) => items.map((entry, itemIndex) => itemIndex === index ? { ...entry, variantSku: "" } : entry))} style={[styles.mediaVariant, !item.variantSku && styles.mediaVariantActive]}><Text style={[styles.mediaVariantText, !item.variantSku && styles.mediaVariantTextActive]}>All</Text></Pressable>{variants.slice(0, 4).map((variant) => <Pressable key={variant.sku || variant.title} onPress={() => setMedia((items) => items.map((entry, itemIndex) => itemIndex === index ? { ...entry, variantSku: variant.sku } : entry))} style={[styles.mediaVariant, item.variantSku === variant.sku && styles.mediaVariantActive]}><Text numberOfLines={1} style={[styles.mediaVariantText, item.variantSku === variant.sku && styles.mediaVariantTextActive]}>{variant.sku || variant.title}</Text></Pressable>)}</View><Text style={styles.mediaOrder}>IMAGE {index + 1}{index === 0 ? " · COVER" : ""}</Text></View>)}{media.length < 12 ? <Pressable disabled={uploading} onPress={() => void uploadImage()} style={styles.addMedia}>{uploading ? <ActivityIndicator color={colors.primary} /> : <><Ionicons color={colors.primary} name="cloud-upload-outline" size={27} /><Text style={styles.addMediaTitle}>Add image</Text><Text style={styles.addMediaMeta}>Up to 10 MB</Text></>}</Pressable> : null}</View>{uploadError ? <Text style={styles.error}>{uploadError}</Text> : null}</ModuleCard>
    <ModuleCard title="Variant generator" meta="Choose common colors, add custom colors or sizes, then generate the matrix."><ColorOptions onChange={(colorsValue) => setForm({ ...form, colors: colorsValue })} value={form.colors} /><Field label="Sizes (comma separated)" onChangeText={(sizes) => setForm({ ...form, sizes })} placeholder="S, M, L, XL" value={form.sizes} /><Pressable onPress={generateVariants} style={styles.outline}><Ionicons color={colors.primary} name="git-branch-outline" size={18} /><Text style={styles.outlineText}>Generate color and size variants</Text></Pressable></ModuleCard>
    <ModuleCard title={`Variant matrix · ${variants.length}`} meta={`${variants.reduce((sum, variant) => sum + (Number(variant.stock) || 0), 0)} total opening stock`}><View style={styles.variantList}>{variants.map((variant, index) => <View key={variant.id ?? `${index}-${variant.color}-${variant.size}`} style={styles.variantCard}><View style={styles.variantHeader}><View style={styles.variantNumber}><Text style={styles.variantNumberText}>{index + 1}</Text></View><Text style={styles.variantHeading}>{variant.title || `Variant ${index + 1}`}</Text><Pressable disabled={variants.length === 1} onPress={() => setVariants((items) => items.filter((_, itemIndex) => itemIndex !== index))}><Ionicons color={variants.length === 1 ? colors.border : colors.danger} name="trash-outline" size={19} /></Pressable></View><View style={styles.row}><Field label="Color" onChangeText={(color) => updateVariant(index, { color, title: [color, variant.size].filter(Boolean).join(" / ") || "Default" })} value={variant.color} /><Field label="Size" onChangeText={(size) => updateVariant(index, { size, title: [variant.color, size].filter(Boolean).join(" / ") || "Default" })} value={variant.size} /><Field label="SKU *" onChangeText={(sku) => updateVariant(index, { sku: sku.toUpperCase() })} value={variant.sku} /></View><View style={styles.row}><Field keyboardType="decimal-pad" label="Price *" onChangeText={(price) => updateVariant(index, { price })} value={variant.price} /><Field keyboardType="decimal-pad" label="Compare at" onChangeText={(compareAt) => updateVariant(index, { compareAt })} value={variant.compareAt} /><Field keyboardType="numeric" label="Stock *" onChangeText={(stock) => updateVariant(index, { stock })} value={variant.stock} /></View><Pressable onPress={() => updateVariant(index, { active: !variant.active })} style={styles.activeRow}><Ionicons color={variant.active ? colors.success : colors.muted} name={variant.active ? "checkbox" : "square-outline"} size={20} /><Text style={styles.activeText}>Variant is active and sellable</Text></Pressable></View>)}</View><Pressable onPress={() => setVariants((items) => [...items, emptyVariant()])} style={styles.outline}><Ionicons color={colors.primary} name="add" size={18} /><Text style={styles.outlineText}>Add another variant</Text></Pressable></ModuleCard>
    {!uniqueSkus ? <Text style={styles.error}>Every variant needs a unique SKU.</Text> : null}{!requiredAttributesValid ? <Text style={styles.error}>Complete every required category field.</Text> : null}{formError ? <Text style={styles.error}>{formError}</Text> : null}{save.error ? <Text style={styles.error}>{save.error.message}</Text> : null}<View style={[styles.footer, compact && compactStyles.footer]}><Pressable onPress={() => router.back()} style={[styles.cancel, compact && compactStyles.footerButton]}><Text style={styles.cancelText}>Cancel</Text></Pressable><Pressable disabled={!valid || save.isPending || uploading || !user} onPress={() => save.mutate(user!)} style={[styles.primary, compact && compactStyles.footerButton, (!valid || save.isPending || uploading || !user) && styles.disabled]}>{save.isPending ? <ActivityIndicator color={colors.surface} /> : <Text style={styles.primaryText}>{editing ? "Save product and variants" : "Create draft product"}</Text>}</Pressable></View>
  </Screen>;
}

type CategoryAttribute = CategoryDto["attributes"][number];
const compactStyles = StyleSheet.create({ steps: { paddingHorizontal: spacing.sm }, footer: { alignItems: "stretch", flexDirection: "column-reverse" }, footerButton: { minWidth: 0, width: "100%" } });
const colorChoices = [{ name: "Black", hex: "#111827" }, { name: "White", hex: "#ffffff" }, { name: "Red", hex: "#ef4444" }, { name: "Blue", hex: "#2563eb" }, { name: "Green", hex: "#16a34a" }, { name: "Yellow", hex: "#facc15" }, { name: "Orange", hex: "#f97316" }, { name: "Pink", hex: "#ec4899" }, { name: "Purple", hex: "#9333ea" }, { name: "Brown", hex: "#92400e" }, { name: "Gray", hex: "#6b7280" }, { name: "Multi", hex: "#0ea5e9" }];

function DynamicAttributeField({ attribute, onChange, value }: { attribute: CategoryAttribute; onChange(value: unknown): void; value: unknown }) {
  const label = `${attribute.label}${attribute.required ? " *" : ""}`;
  if (attribute.dataType === "boolean") return <Pressable accessibilityRole="checkbox" accessibilityState={{ checked: value === true }} onPress={() => onChange(value !== true)} style={extraStyles.boolean}><Ionicons color={value === true ? colors.success : colors.muted} name={value === true ? "checkbox" : "square-outline"} size={21} /><Text style={styles.label}>{label}</Text></Pressable>;
  if (attribute.dataType === "select" || attribute.dataType === "multiselect") {
    const selected = attribute.dataType === "multiselect" ? (Array.isArray(value) ? value : []) : [value];
    return <View style={extraStyles.attribute}><Text style={styles.label}>{label}</Text><View style={extraStyles.optionChips}>{attribute.options.map((option) => { const active = selected.includes(option.value); return <Pressable key={option.id} onPress={() => onChange(attribute.dataType === "multiselect" ? active ? selected.filter((item) => item !== option.value) : [...selected, option.value] : option.value)} style={[extraStyles.optionChip, active && extraStyles.optionChipActive]}><Text style={[extraStyles.optionChipText, active && extraStyles.optionChipTextActive]}>{option.label}</Text></Pressable>; })}</View></View>;
  }
  return <Field keyboardType={attribute.dataType === "number" ? "decimal-pad" : "default"} label={label} onChangeText={(text) => onChange(attribute.dataType === "number" ? text.replace(/[^0-9.]/g, "") : text)} placeholder={`Enter ${attribute.label.toLowerCase()}`} value={typeof value === "string" || typeof value === "number" ? String(value) : ""} />;
}

function ColorOptions({ onChange, value }: { onChange(value: string): void; value: string }) {
  const selected = values(value);
  const toggle = (name: string) => onChange((selected.some((item) => item.toLowerCase() === name.toLowerCase()) ? selected.filter((item) => item.toLowerCase() !== name.toLowerCase()) : [...selected, name]).join(", "));
  return <View style={extraStyles.attribute}>
    <Text style={styles.label}>Colors</Text>
    <View style={extraStyles.colorGrid}>{colorChoices.map((choice) => {
      const active = selected.some((item) => item.toLowerCase() === choice.name.toLowerCase());
      return <Pressable accessibilityRole="checkbox" accessibilityState={{ checked: active }} key={choice.name} onPress={() => toggle(choice.name)} style={[extraStyles.colorChip, active && extraStyles.colorChipActive]}>
        <View style={[extraStyles.swatch, { backgroundColor: choice.hex }, choice.name === "White" && extraStyles.whiteSwatch]} />
        <Text style={extraStyles.colorText}>{choice.name}</Text>
        {active ? <Ionicons color={colors.primary} name="checkmark-circle" size={16} /> : null}
      </Pressable>;
    })}</View>
    <Field label="Custom colors (comma separated)" onChangeText={onChange} placeholder="Navy, Rose Gold" value={value} />
  </View>;
}

function Field(props: React.ComponentProps<typeof TextInput> & { label: string }) { const { label, ...input } = props; return <View style={styles.field}><Text style={styles.label}>{label}</Text><TextInput placeholderTextColor={colors.muted} style={[styles.input, input.multiline && styles.multiline]} {...input} /></View>; }
function Step({ complete, label, number }: { complete: boolean; label: string; number: string }) { return <View style={styles.step}><View style={[styles.stepNumber, complete && styles.stepActive]}>{complete ? <Ionicons color={colors.surface} name="checkmark" size={16} /> : <Text style={styles.stepNumberText}>{number}</Text>}</View><Text style={[styles.stepLabel, complete && styles.stepLabelComplete]}>{label}</Text></View>; }
function values(value: string) { return unique(value.split(",").map((item) => item.trim()).filter(Boolean)); }
function unique(valuesInput: string[]) { return [...new Set(valuesInput.filter(Boolean))]; }
function slug(value: string) { return value.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, ""); }
function minor(value: string) { const amount = parseMajorToMinor(value); if (amount === null) throw new Error("Variant price must be a valid amount with at most two decimals."); return amount.toString(); }
function decimal(value: string) { return minorToMajorInput(value); }
function validVariant(variant: VariantDraft) { const price = parseMajorToMinor(variant.price); const compareAt = variant.compareAt ? parseMajorToMinor(variant.compareAt) : null; const stock = Number(variant.stock); return variant.sku.trim().length >= 3 && variant.title.trim().length > 0 && price !== null && price > 0n && Number.isInteger(stock) && stock >= 0 && (!variant.compareAt || compareAt !== null && compareAt >= price); }
function textAttribute(value: unknown) { return typeof value === "string" ? value : ""; }
function hasAttributeValue(value: unknown) { return value === true || typeof value === "number" || (typeof value === "string" && value.trim().length > 0) || (Array.isArray(value) && value.length > 0); }
function inheritedAttributes(categories: CategoryDto[], categoryId: string) { const byId = new Map(categories.map((category) => [category.id, category])); const path: CategoryDto[] = []; const visited = new Set<string>(); let current = byId.get(categoryId); while (current && !visited.has(current.id)) { path.unshift(current); visited.add(current.id); current = current.parentId ? byId.get(current.parentId) : undefined; } const attributes = new Map<string, CategoryAttribute>(); path.forEach((category) => category.attributes.forEach((attribute) => attributes.set(attribute.key, attribute))); return [...attributes.values()].sort((left, right) => left.displayOrder - right.displayOrder); }
function makeSku(name: string, color: string, size: string, index: number) { const part = (value: string, fallback: string) => value.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 6) || fallback; return `${part(name, "ITEM")}-${part(color, "CLR")}-${part(size, String(index + 1))}`; }
